# Format output as {format}
import json
import csv
import sys
data = {data}
format_type = '{format}'

if format_type == 'json':
    print(json.dumps(data, indent=2))
elif format_type == 'csv':
    if isinstance(data, list):
        writer = csv.writer(sys.stdout)
        for row in data:
            if isinstance(row, (list, tuple)):
                writer.writerow(row)
            else:
                writer.writerow([row])
    else:
        print(str(data))
else:  # text
    print(data)
